using System;
using System.Diagnostics;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;

namespace StickyNotes;
public sealed class LibraryWindow:Window {
 readonly NotesApp app;readonly Border surface;readonly Grid root=new();readonly StackPanel body=new();readonly TextBox search;readonly ComboBox areas=new();bool refreshing;bool settings;bool trash;
 public LibraryWindow(NotesApp app){this.app=app;Title="Sticky Notes — Notas e áreas";Visuals.Base(this,470,650);surface=Visuals.Surface(this,Visuals.Dark(app.Store.Book.Theme));surface.Child=root;root.RowDefinitions.Add(new(){Height=GridLength.Auto});root.RowDefinitions.Add(new(){Height=GridLength.Auto});root.RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});
  var title=Visuals.Label("Sticky Notes",23);title.FontWeight=FontWeights.SemiBold;title.MouseLeftButtonDown+=(_,_)=>DragMove();var head=new DockPanel{Margin=new Thickness(0,0,0,18)};var close=Visuals.Icon("\uE8BB","Fechar painel",Close);DockPanel.SetDock(close,Dock.Right);head.Children.Add(close);head.Children.Add(title);root.Children.Add(head);
  var bar=new StackPanel();search=Visuals.Input("Buscar em todas as notas");search.Background=Visuals.Brush(Visuals.Dark(app.Store.Book.Theme)?"#383B43":"#ECECF1");search.Foreground=Foreground;search.Padding=new Thickness(10);search.ToolTip="Buscar em todas as áreas";search.TextChanged+=(_,_)=>Render();bar.Children.Add(Visuals.Label("BUSCAR EM TODAS AS ÁREAS",10));bar.Children.Add(search);
  var nav=new WrapPanel{Margin=new Thickness(0,10,0,10)};nav.Children.Add(Visuals.TextButton("Notas",()=>{settings=false;trash=false;Refresh();}));nav.Children.Add(Visuals.TextButton("Lixeira",()=>{settings=false;trash=true;Refresh();}));nav.Children.Add(Visuals.TextButton("Configurações",()=>{settings=true;Refresh();}));bar.Children.Add(nav);Grid.SetRow(bar,1);root.Children.Add(bar);
  var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,2);root.Children.Add(scroll);areas.SelectionChanged+=(_,_)=>{if(!refreshing&&areas.SelectedItem is string a){app.SwitchArea(a);Render();}};
  SourceInitialized+=(_,_)=>{var r=SystemParameters.WorkArea;Height=Math.Min(650,r.Height-24);Left=r.Right-Width-12;Top=r.Bottom-Height-12;};PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape)Close();};Loaded+=(_,_)=>Visuals.Reveal(this,surface);
 }
 public void Refresh(bool showSettings=false){if(showSettings)settings=true;bool dark=Visuals.Dark(app.Store.Book.Theme);surface.Background=Visuals.Brush(dark?"#F524262B":"#F8F8F8FA");Foreground=Visuals.Brush(dark?"#F5F5F7":"#252730");search.Foreground=Foreground;search.Background=Visuals.Brush(dark?"#383B43":"#ECECF1");Render();}
 void Render(){if(refreshing)return;refreshing=true;try{body.Children.Clear();if(settings){RenderSettings();return;}if(!trash){body.Children.Add(Visuals.Label("ÁREA ATIVA",10));areas.ItemsSource=app.Store.Book.Areas.ToList();areas.SelectedItem=app.Store.Book.ActiveArea;areas.MinHeight=34;areas.Margin=new Thickness(0,3,0,10);body.Children.Add(areas);var row=new WrapPanel();row.Children.Add(Visuals.TextButton("+ Nova nota",()=>app.NewNote()));row.Children.Add(Visuals.TextButton("Alinhar em grade",app.Arrange));body.Children.Add(row);}
  var q=search.Text.Trim();var notes=app.Store.Book.Notes.Where(n=>n.Deleted==trash&&(q.Length>0?(n.Title+" "+n.Preview).Contains(q,StringComparison.CurrentCultureIgnoreCase):trash||n.Area==app.Store.Book.ActiveArea)).OrderByDescending(n=>n.Updated).ToList();body.Children.Add(Visuals.Label((trash?"LIXEIRA":"NOTAS")+" · "+notes.Count,10));
  if(notes.Count==0)body.Children.Add(Visuals.Label(trash?"Nenhuma nota na lixeira.":"Uma mesa livre para novas ideias. Crie sua primeira nota.",15));
  foreach(var n in notes){var card=new Border{CornerRadius=new CornerRadius(8),Padding=new Thickness(12),Margin=new Thickness(0,5,0,5),BorderThickness=new Thickness(3,0,0,0),BorderBrush=Visuals.Brush(n.Color),Background=Visuals.Brush(Visuals.Dark(app.Store.Book.Theme)?"#34363D":"#ECECF1")};var stack=new StackPanel();var label=Visuals.Label(n.Title,16);label.FontWeight=FontWeights.SemiBold;stack.Children.Add(label);stack.Children.Add(Visuals.Label(n.Area+" · "+n.Updated.ToLocalTime().ToString("dd/MM HH:mm"),10));var preview=Visuals.Label(n.Preview.Length>130?n.Preview[..130]+"…":n.Preview,12);preview.MaxHeight=48;preview.Opacity=.7;stack.Children.Add(preview);stack.Children.Add(Visuals.TextButton(trash?"Restaurar nota":"Abrir nota",()=>{if(trash){n.Deleted=false;app.Store.Save();}app.ShowNote(n);Render();}));card.Child=stack;body.Children.Add(card);}
 }finally{refreshing=false;}}
 void RenderSettings(){body.Children.Add(Visuals.Label("APARÊNCIA",10));var theme=new ComboBox{ItemsSource=new[]{"Sistema","Claro","Escuro"},SelectedItem=app.Store.Book.Theme,MinHeight=34,Margin=new Thickness(0,6,0,16)};theme.SelectionChanged+=(_,_)=>{app.Store.Book.Theme=(string)theme.SelectedItem;app.Store.Save();app.ApplyTheme();};body.Children.Add(theme);
  var startup=new CheckBox{Content="Iniciar com o Windows, apenas na bandeja",IsEnabled=false,Margin=new Thickness(0,6,0,16)};async System.Threading.Tasks.Task ReadStartup(){try{startup.IsChecked=await app.StartupEnabledAsync();startup.IsEnabled=true;}catch(Exception e){startup.ToolTip=e.Message;}}startup.Click+=async(_,_)=>{startup.IsEnabled=false;try{await app.SetStartup(startup.IsChecked==true);}catch(Exception e){Visuals.Error(e.Message);}finally{await ReadStartup();}};body.Children.Add(startup);_=ReadStartup();
  body.Children.Add(Visuals.Label("ÁREAS DA SUA MESA",10));body.Children.Add(Visuals.Label("Separe trabalho, ideias e assuntos pessoais. Cada área guarda suas notas e posições.",12));var name=Visuals.Input("Nome da nova área");name.Background=search.Background;name.Foreground=Foreground;name.Padding=new Thickness(8);body.Children.Add(name);body.Children.Add(Visuals.TextButton("Criar área",()=>{string a=name.Text.Trim();if(a.Length==0||a.Length>50){Visuals.Error("Dê à área um nome de 1 a 50 caracteres.");return;}if(app.Store.Book.Areas.Any(x=>x.Equals(a,StringComparison.CurrentCultureIgnoreCase))){Visuals.Error("Já existe uma área com esse nome.");return;}app.Store.Book.Areas.Add(a);app.Store.Save();app.SwitchArea(a);settings=false;Refresh();}));
  body.Children.Add(Visuals.Label("SEUS DADOS",10));body.Children.Add(Visuals.Label("Notas e imagens ficam neste computador. Não é preciso conta nem conexão. A lixeira guarda as notas até você restaurá-las.",12));body.Children.Add(Visuals.TextButton("Exportar backup completo…",app.ExportBackup));body.Children.Add(Visuals.TextButton("Abrir pasta de dados",()=>Process.Start(new ProcessStartInfo(app.DataRoot){UseShellExecute=true})));body.Children.Add(Visuals.Label("Ctrl+N · nova nota\nCtrl+B / Ctrl+I · formatação\nCtrl+V · colar texto ou imagem\nEsc · ocultar nota\nCtrl+Shift+H · ocultar todas",12));body.Children.Add(Visuals.Label("Windows Sticky Notes "+Distribution.Version,10));
 }
}
